// Revisa la configuración, la sesión de Clerk y el hash, y deja pasar el pedido nada más si todo está en orden.
const crypto = require('crypto');
const item = $input.first().json;
const rechazo = (codigo, motivo) => [{ json: { valido: false, codigo, motivo } }];

// 1. Configuración: la clave pública de Clerk (PEM) y la dirección que cobra
let clave;
try {
  clave = crypto.createPublicKey(String(item.clerk_clave_publica ?? '').trim());
} catch (e) {
  return rechazo(500, 'Falta configurar clerk_clave_publica: pegá la JWKS Public Key de Clerk en formato PEM en el nodo Configuración.');
}
const tienda = String(item.direccion_tienda ?? '').trim().toLowerCase();
if (!/^0x[0-9a-f]{40}$/.test(tienda)) {
  return rechazo(500, 'Falta configurar direccion_tienda: la dirección 0x de Fuji que cobra, en el nodo Configuración.');
}
// El monto mínimo va en AVAX, como texto: «0.01» (también se acepta «0,01»). Se pasa a wei en Verificar el pago.
const montoMinimo = String(item.monto_minimo_avax ?? '').trim().replace(',', '.');
if (!/^\d+(\.\d{1,18})?$/.test(montoMinimo)) {
  return rechazo(500, 'Revisá monto_minimo_avax en el nodo Configuración: un monto en AVAX, por ejemplo 0.01 (hasta 18 decimales).');
}
const confirmacionesMinimas = Number(item.confirmaciones_minimas ?? 1);
if (!Number.isInteger(confirmacionesMinimas) || confirmacionesMinimas < 0) {
  return rechazo(500, 'Revisá confirmaciones_minimas en el nodo Configuración: un número entero, 0 o más.');
}

// 2. El token de sesión llega en la cabecera «Authorization: Bearer <token>»
const token = String(item.headers?.authorization ?? '').match(/^Bearer\s+(\S+)$/i)?.[1];
if (!token) return rechazo(401, 'Falta el token de sesión: mandalo en la cabecera Authorization: Bearer <token>.');
const partes = token.split('.');
if (partes.length !== 3) return rechazo(401, 'El token no tiene la forma de un JWT.');
let cabecera, datos;
try {
  cabecera = JSON.parse(Buffer.from(partes[0], 'base64url').toString('utf8'));
  datos = JSON.parse(Buffer.from(partes[1], 'base64url').toString('utf8'));
} catch (e) {
  return rechazo(401, 'No se pudo leer el token.');
}
if (cabecera.alg !== 'RS256') return rechazo(401, 'El token no está firmado con RS256.');

// 3. La firma: prueba que el token lo emitió tu aplicación de Clerk y que nadie lo cambió
const firmaOk = crypto.createVerify('RSA-SHA256').update(`${partes[0]}.${partes[1]}`).verify(clave, Buffer.from(partes[2], 'base64url'));
if (!firmaOk) return rechazo(401, 'La firma del token no es válida para esta aplicación de Clerk.');

// 4. Vigencia (exp y nbf), con 5 segundos de margen por diferencias de reloj
const ahora = Math.floor(Date.now() / 1000);
if (typeof datos.exp !== 'number' || datos.exp < ahora - 5) return rechazo(401, 'El token venció: pedí uno nuevo con getToken() justo antes de llamar.');
if (typeof datos.nbf === 'number' && datos.nbf > ahora + 5) return rechazo(401, 'El token todavía no es válido.');

// 5. Origen (azp): que el token salga de tu página. Si dejás origenes_permitidos vacío, no se revisa.
const origenes = String(item.origenes_permitidos ?? '').split(',').map((o) => o.trim()).filter(Boolean);
if (origenes.length && datos.azp && !origenes.includes(datos.azp)) {
  return rechazo(401, `El token salió de ${datos.azp}, que no está en origenes_permitidos.`);
}
if (!datos.sub) return rechazo(401, 'El token no trae el id de la persona (sub).');

// 6. El hash del pago
const txHash = String(item.body?.txHash ?? '').trim().toLowerCase();
if (!/^0x[0-9a-f]{64}$/.test(txHash)) {
  return rechazo(400, 'Falta txHash o no tiene la forma de un hash de Fuji: 0x y 64 caracteres hexadecimales.');
}

return [{
  json: {
    valido: true,
    codigo: 200,
    clerk_id: datos.sub,
    txHash,
    direccion_tienda: tienda,
    monto_minimo_avax: montoMinimo,
    confirmaciones_minimas: confirmacionesMinimas,
  },
}];

// Aplica las reglas del pago a lo que respondió Fuji: estado, destino, monto y confirmaciones.
const pedido = $('Verificar sesión de Clerk').first().json;
// El lote JSON-RPC devuelve una respuesta por pedido; se ordenan por id (1 transacción, 2 recibo, 3 último bloque).
const respuestas = $input.all().map((i) => i.json);
const r = Object.fromEntries(respuestas.map((x) => [x.id, x]));
const tx = r[1]?.result ?? null;
const recibo = r[2]?.result ?? null;
const ultimo = r[3]?.result ? BigInt(r[3].result) : null;

// 1 AVAX = 10^18 wei. Se pasa con texto y BigInt para no perder precisión con decimales.
const aWei = (avax) => {
  const [entero, decimales = ''] = String(avax).trim().split('.');
  return BigInt(entero || '0') * 10n ** 18n + BigInt((decimales + '0'.repeat(18)).slice(0, 18) || '0');
};
const aAvax = (wei) => {
  const base = 10n ** 18n;
  const resto = (wei % base).toString().padStart(18, '0').replace(/0+$/, '');
  return resto ? `${wei / base}.${resto}` : `${wei / base}`;
};

const motivos = [];
// Si falla el pedido entero (la red, o el RPC limita los pedidos), llega un único ítem con «error» y sin id:
// Leer el pago en Fuji tiene On Error: Continue para que la API responda igual, con 502.
const errorRpc = respuestas.find((x) => x?.error)?.error ?? (!r[1] || !r[2] || !r[3] ? { message: 'la respuesta llegó incompleta' } : null);
if (errorRpc) motivos.push(`El RPC de Fuji respondió un error: ${errorRpc.message ?? JSON.stringify(errorRpc)}. Probá de nuevo en un momento.`);

const pago = {
  txHash: pedido.txHash,
  explorador: `https://build.avax.network/explorer/fuji/c-chain/tx/${pedido.txHash}`,
  clerk_id: pedido.clerk_id,
};
if (!tx) {
  if (!errorRpc) motivos.push('La transacción no existe en Fuji: revisá el hash y que sea de la red de prueba.');
} else {
  const valor = BigInt(tx.value);
  const bloque = tx.blockNumber ? BigInt(tx.blockNumber) : null;
  // Si ya está en un bloque, tiene por lo menos 1 confirmación: el «último bloque» del RPC público a veces llega uno atrasado.
  const confirmaciones = bloque !== null && ultimo !== null ? Math.max(1, Number(ultimo - bloque + 1n)) : 0;
  Object.assign(pago, {
    desde: tx.from.toLowerCase(),
    hacia: String(tx.to ?? '').toLowerCase(),
    monto_wei: valor.toString(),
    monto_avax: aAvax(valor),
    bloque: bloque === null ? null : Number(bloque),
    confirmaciones,
  });
  if (!recibo) motivos.push('La transacción todavía no tiene recibo: esperá unos segundos y volvé a probar.');
  else if (recibo.status !== '0x1') motivos.push('La transacción falló en la red (status 0x0).');
  if (pago.hacia !== pedido.direccion_tienda) {
    motivos.push(`El pago fue a ${pago.hacia || 'ninguna dirección (creó un contrato)'} y no a la dirección que cobra.`);
  }
  if (valor < aWei(pedido.monto_minimo_avax)) {
    motivos.push(`El monto (${pago.monto_avax} AVAX) es menor que el mínimo (${pedido.monto_minimo_avax} AVAX).`);
  }
  if (confirmaciones < pedido.confirmaciones_minimas) {
    motivos.push(`Tiene ${confirmaciones} confirmaciones y se piden ${pedido.confirmaciones_minimas}.`);
  }
}

return [{ json: { verificado: motivos.length === 0, error_rpc: Boolean(errorRpc), motivos, minimo_avax: pedido.monto_minimo_avax, pago } }];
